const updateCookKvkRegistration = `-- name: UpdateCookKvkRegistration :execrows
UPDATE cook_profiles
SET kvk_number              = $1,
    kvk_trade_name          = $2,
    registration_status     = $3,
    registration_checked_at = $4,
    updated_at              = NOW()
WHERE id = $5
  AND anonymised_at IS NULL
`

type UpdateCookKvkRegistrationParams struct {
	KvkNumber             *string                `json:"kvk_number"`
	KvkTradeName          *string                `json:"kvk_trade_name"`
	RegistrationStatus    CookRegistrationStatus `json:"registration_status"`
	RegistrationCheckedAt pgtype.Timestamptz     `json:"registration_checked_at"`
	ID                    pgtype.UUID            `json:"id"`
}

// A changed KvK number after a definite check result ('active' or 'inactive'), or 'pending'
// with NULLs when the register was unreachable. Rejected numbers (not found / inactive on PATCH)
// must not call this: the old number stays in effect.
func (q *Queries) UpdateCookKvkRegistration(ctx context.Context, arg UpdateCookKvkRegistrationParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateCookKvkRegistration,
		arg.KvkNumber,
		arg.KvkTradeName,
		arg.RegistrationStatus,
		arg.RegistrationCheckedAt,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateCookProfile = `-- name: UpdateCookProfile :execrows
UPDATE cook_profiles
SET display_name                = COALESCE($1, display_name),
    org_type                    = COALESCE($2, org_type),
    phone                       = COALESCE($3, phone),
    default_pickup_address_text = COALESCE($4, default_pickup_address_text),
    default_pickup_location     = CASE
        WHEN $5::float8 IS NOT NULL AND $6::float8 IS NOT NULL
        THEN ST_SetSRID(ST_MakePoint($5::float8, $6::float8), 4326)::geography
        ELSE default_pickup_location
    END,
    updated_at                  = NOW()
WHERE id = $7
  AND anonymised_at IS NULL
`

type UpdateCookProfileParams struct {
	DisplayName              *string      `json:"display_name"`
	OrgType                  *CookOrgType `json:"org_type"`
	Phone                    *string      `json:"phone"`
	DefaultPickupAddressText *string      `json:"default_pickup_address_text"`
	PickupLng                *float64     `json:"pickup_lng"`
	PickupLat                *float64     `json:"pickup_lat"`
	ID                       pgtype.UUID  `json:"id"`
}

// PATCH /me/cook-profile for everything except the KvK number (see UpdateCookKvkRegistration)
// and the declaration (cannot be withdrawn). NULL arguments leave the column unchanged. The
// latitude and longitude must be passed together. Never touches anonymised profiles.
func (q *Queries) UpdateCookProfile(ctx context.Context, arg UpdateCookProfileParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateCookProfile,
		arg.DisplayName,
		arg.OrgType,
		arg.Phone,
		arg.DefaultPickupAddressText,
		arg.PickupLng,
		arg.PickupLat,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateCookRegistrationResult = `-- name: UpdateCookRegistrationResult :execrows
UPDATE cook_profiles
SET registration_status     = $1,
    kvk_trade_name          = COALESCE($2, kvk_trade_name),
    registration_checked_at = $3,
    updated_at              = NOW()
WHERE id = $4
  AND kvk_number = $5
  AND anonymised_at IS NULL
`

type UpdateCookRegistrationResultParams struct {
	RegistrationStatus    CookRegistrationStatus `json:"registration_status"`
	KvkTradeName          *string                `json:"kvk_trade_name"`
	RegistrationCheckedAt pgtype.Timestamptz     `json:"registration_checked_at"`
	ID                    pgtype.UUID            `json:"id"`
	KvkNumber             *string                `json:"kvk_number"`
}

// Result of a (re-)check by the background job (FR-021). Only call with a definite answer
// ('active' or 'inactive'); a transport error must not call this, so an active profile is never
// downgraded by an outage. A NULL trade name keeps the stored one. Guarded by the kvk_number
// the check was run for, so a concurrent PATCH of the number is not overwritten.
func (q *Queries) UpdateCookRegistrationResult(ctx context.Context, arg UpdateCookRegistrationResultParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateCookRegistrationResult,
		arg.RegistrationStatus,
		arg.KvkTradeName,
		arg.RegistrationCheckedAt,
		arg.ID,
		arg.KvkNumber,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
